const extensions = new Set([
  "png",
  "jpg",
  "jpeg",
  "gif",
  "webp",
  "avif",
  "heic",
  "img",
]);
/** Only names generated by this app inside its dedicated media directory. */
export function ownedImageName(
  name: string,
): { base: string; partial: boolean } | null {
  const partial = name.endsWith(".partial");
  let base = partial ? name.slice(0, -8) : name;
  if (partial && /^[0-9a-f]{64}\./.test(base)) {
    const numbered = /^(.*)\.[1-9][0-9]*$/.exec(base);
    if (!numbered) return null;
    base = numbered[1];
  }
  const match =
    /^([0-9a-f]{64}|(?:0|[1-9a-f][0-9a-f]{0,7})-[1-9][0-9]{0,9})\.([a-zA-Z]+)$/.exec(
      base,
    );
  if (!match || !extensions.has(match[2].toLowerCase())) return null;
  if (match[1].includes("-") && Number(match[1].split("-")[1]) > 4294967295)
    return null;
  return { base: base.toLowerCase(), partial };
}
